#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=9
ENV_FILE=".env.eas.local"

require_value() {
  local name="$1" value="$2"
  if [[ -z "$value" ]]; then warn "$name cannot be empty."; exit 1; fi
}

banner "MOSTLYVERS Android · EAS and APK setup"

stage "Verify the production API"
ask API_ORIGIN "Render origin (example: https://mostlyvers-api.onrender.com):"
API_ORIGIN="${API_ORIGIN%/}"
if [[ "$API_ORIGIN" != https://* || "$API_ORIGIN" == */v1 ]]; then
  warn "Enter the HTTPS Render origin without /v1 or a trailing slash."
  exit 1
fi
write_env EXPO_PUBLIC_API_URL "$API_ORIGIN/v1"
chmod 600 "$ENV_FILE"
say "Waking and checking Render; a free instance may need about a minute."
curl --retry 6 --retry-delay 10 --retry-all-errors --max-time 180 --fail --silent --show-error "$API_ORIGIN/health/ready"
printf '\n'

stage "Sign in to Expo and link EAS"
if ! npx eas-cli@latest whoami >/dev/null 2>&1; then
  npx eas-cli@latest login
fi
npx eas-cli@latest whoami
say "Create or link the EAS project for slug mostlyvers."
npx eas-cli@latest init
PROJECT_ID=$(npx expo config --type public --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const c=JSON.parse(s);process.stdout.write(c.extra?.eas?.projectId||"")})')
if [[ -z "$PROJECT_ID" ]]; then
  ask PROJECT_ID "Paste the EAS project UUID shown by eas init or expo.dev:"
fi
require_value EXPO_PUBLIC_EAS_PROJECT_ID "$PROJECT_ID"
write_env EXPO_PUBLIC_EAS_PROJECT_ID "$PROJECT_ID"
PROJECT_ID="$PROJECT_ID" node -e 'const fs=require("fs");const p="app.json";const j=JSON.parse(fs.readFileSync(p,"utf8"));j.expo.extra={...(j.expo.extra||{}),eas:{...(j.expo.extra?.eas||{}),projectId:process.env.PROJECT_ID}};fs.writeFileSync(p,JSON.stringify(j,null,2)+"\n")'

stage "Configure EAS environment variables"
open_url "https://expo.dev/accounts"
step "Open your MOSTLYVERS project → Environment variables."
step "Add EXPO_PUBLIC_API_URL as Plain text for Preview and Production:"
say "$API_ORIGIN/v1"
step "Add EXPO_PUBLIC_EAS_PROJECT_ID as Plain text for Development, Preview, and Production:"
say "$PROJECT_ID"
step "Do not add passwords, database URLs, API secrets, or service-account JSON as EXPO_PUBLIC variables."
pause "Press Enter after both variables appear in the selected EAS environments."

stage "Register the Android app in Firebase"
open_url "https://console.firebase.google.com/"
step "Create/open the Firebase project, then Project settings → Your apps → Add app → Android."
step "Use Android package name com.mostlyvers.app. The nickname is optional."
step "Download google-services.json. Do not rename or edit it."
step "In Expo project → Environment variables, upload it as a File variable named GOOGLE_SERVICES_JSON for Preview and Production."
pause "Press Enter after the GOOGLE_SERVICES_JSON file variable is present in both environments."

stage "Configure FCM V1 sending credentials"
say "The app-side Firebase file and the server-side FCM credential are different files."
open_url "https://console.firebase.google.com/"
step "Firebase Project settings → Service accounts → Generate new private key."
step "In expo.dev → Project → Credentials → Android → com.mostlyvers.app → FCM V1 service account key, upload that private-key JSON."
step "Delete the downloaded service-account file after Expo confirms the upload; never commit it."
pause "Press Enter after Expo shows an FCM V1 credential for com.mostlyvers.app."

stage "Commit the EAS project link"
say "Only the non-secret EAS project UUID should have changed in app.json."
npx expo config --type public >/dev/null
git diff --check
git status --short
if confirm "Commit and push the EAS project link now?"; then
  git add app.json
  if ! git diff --cached --quiet; then git commit -m "Link Android app to EAS project"; fi
  git push origin main
else
  SKIPPED+=("commit and push app.json EAS project link")
fi

stage "Build the installable Android APK"
say "The staging profile is a release-like internal APK and uses the EAS Preview environment."
if confirm "Start the cloud APK build now?"; then
  npx eas-cli@latest build --platform android --profile staging
else
  SKIPPED+=("eas build --platform android --profile staging")
fi

stage "Install on the physical phone"
step "Open the EAS build URL on the Android phone and download the APK."
step "Allow Install unknown apps for the browser/file manager when Android asks."
step "Install MOSTLYVERS, open it, and allow notification permission."
step "This APK is standalone: Metro, Expo Go, and your Mac do not need to be running."
pause "Press Enter after the app opens on the phone."

stage "Physical-device acceptance test"
step "Create a reader using the email OTP, log out, and log back in."
step "Confirm Home, Latest, Upcoming, profile, notifications, and password recovery load from Render."
step "From admin, upload a cover and EPUB, wait for processing, publish it, then refresh Android."
step "Claim the book, open it, save progress/bookmark, download it, enable airplane mode, and reopen it."
step "Submit feedback and verify protected YouTube access."
step "Send an admin notification and confirm the inbox item; push delivery additionally requires the FCM stage above."
step "Only after all checks pass, run: npx eas-cli@latest build --platform android --profile production"
note "The production command creates an AAB for Google Play. It is not directly installable like the staging APK."
pause "Press Enter after recording any failed step and its requestId."

finish
